<script setup lang="ts">
import type {CapabilityRow,CapabilityMode} from '../api/collaboration.js';
import {useI18n} from 'vue-i18n';
const props=defineProps<{rows:CapabilityRow[];draft:Record<string,CapabilityMode>;defaults?:Partial<Record<string,CapabilityMode>>;disabled?:boolean}>();
defineEmits<{save:[]}>();
const {t,te}=useI18n();
function label(code:string){const key=`collaboration.accessCodes.${code.replaceAll('.','_')}`;return te(key)?t(key):`${t('collaboration.unknown')} (${code})`;}
function local(row:CapabilityRow){return props.defaults!==undefined?props.defaults[row.code]??'inherit':row.mode;}
</script>
<template><div class="access-table"><div class="table-scroll"><table><thead><tr><th>{{t('collaboration.capability')}}</th><th>{{t('collaboration.local')}}</th><th>{{t('collaboration.effective')}}</th><th>{{t('collaboration.source')}}</th><th>{{t('collaboration.roleFloor')}}</th><th>{{t('collaboration.permissionReason')}}</th><th>{{t('collaboration.draft')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.code" :data-testid="`capability-${row.code}`"><th>{{label(row.code)}}</th><td>{{label(local(row))}}</td><td>{{label(row.effective?'allow':'deny')}}</td><td>{{label(row.source)}}</td><td>{{te('scheduling.roles.'+row.roleFloor)?t('scheduling.roles.'+row.roleFloor):row.roleFloor}}</td><td>{{label(row.reason)}}</td><td><select v-model="draft[row.code]" :disabled="disabled" :aria-label="label(row.code)" :data-testid="`capability-input-${row.code}`"><option disabled value="">{{t('collaboration.keep')}}</option><option v-for="mode in ['inherit','allow','deny']" :key="mode" :value="mode">{{label(mode)}}</option></select><span v-if="draft[row.code]">{{label(draft[row.code]!)}}</span></td></tr></tbody></table></div><p>{{t('collaboration.permissionHint')}}</p><button :disabled="disabled" data-testid="capability-save" @click="$emit('save')">{{t('collaboration.save')}}</button></div></template>
<style scoped>.access-table{min-width:0}.table-scroll{max-width:100%;overflow:auto}table{width:100%;min-width:900px;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left;white-space:nowrap}select{min-width:160px}p{overflow-wrap:anywhere}</style>
